#!/usr/bin/env node
/**
 * Write test/public-api.generated.ts from build-history/v2.1.1/appendix/public-api.json.
 *
 * The generated file names every 2.1.0 type export, and it checks that every
 * 2.1.0 function export of `athleticstandard/database` satisfies its 2.1.0
 * signature. The npm type check compiles it, so a missing name or an
 * incompatible signature fails the check. test/public-api.test.ts compares
 * the committed file with this output.
 *
 * Usage: node scripts/generate-api-check.mjs [--check]
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = resolve(here, "..");
const inventoryPath = join(packageRoot, "..", "..", "build-history", "v2.1.1", "appendix", "public-api.json");
const outputPath = join(packageRoot, "test", "public-api.generated.ts");

/** Types the 2.1.0 signatures use without exporting them by name. */
const INTERNAL_TYPES = [
  "CompleteRequest",
  "CompleteResponse",
  "ExecuteConfirmedRepairOptions",
  "InstantRange",
];

export function generate(inventory) {
  const symbols = inventory.symbols;
  const typeNames = (entry) =>
    symbols
      .filter((symbol) => symbol.entry_point === entry && symbol.type_export)
      .map((symbol) => symbol.name)
      .sort();
  const schemaTypes = typeNames("./schema");
  const databaseTypes = typeNames("./database").filter(
    (name) => !["MigrationRequiredError", "PackageRepresentationError"].includes(name),
  );
  const lines = [
    "// Generated by scripts/generate-api-check.mjs from build-history/v2.1.1/appendix/public-api.json.",
    "// Do not edit. The npm type check compiles this file.",
    "/* eslint-disable */",
    `import type {\n${schemaTypes.map((name) => `  ${name},`).join("\n")}\n} from "../src/schema.js";`,
    `import type { RecordExtensionsT } from "../src/extensions.js";`,
    `import type {\n${databaseTypes.map((name) => `  ${name},`).join("\n")}\n} from "../src/database.js";`,
    `import type {\n${INTERNAL_TYPES.map((name) => `  ${name},`).join("\n")}\n} from "../src/types.js";`,
    `import type { MigrationRequiredError, PackageRepresentationError } from "../src/database.js";`,
    `import * as database from "../src/database.js";`,
    "",
    "// previewConflict's 2.1.0 signature names these functions with typeof.",
    "const readRecord = database.readRecord;",
    "const readImportedPackageRecord = database.readImportedPackageRecord;",
    "",
    "/** Every 2.1.0 type export by name. */",
    "export type PublicTypes = [",
    ...schemaTypes.map((name) => `  ${name},`),
    ...databaseTypes.map((name) => `  ${name},`),
    "  RecordExtensionsT,",
    "  MigrationRequiredError,",
    "  PackageRepresentationError,",
    "];",
    "",
    "/** Every 2.1.0 function export of ./database with its 2.1.0 signature. */",
    "export const databaseSignatures = {",
  ];
  const functions = symbols
    .filter((symbol) => symbol.entry_point === "./database" && symbol.kinds.includes("function"))
    .sort((left, right) => left.name.localeCompare(right.name));
  for (const symbol of functions) {
    const signatures = symbol.meanings.flatMap((meaning) => meaning.signatures ?? []);
    for (const signature of signatures) {
      const generic = signature.match(/^(<[^>]+>)\s*(\(.*)$/s);
      const type = generic === null
        ? signature.replace(/\):\s*(.*)$/s, ") => $1")
        : `${generic[1]}${generic[2].replace(/\):\s*(.*)$/s, ") => $1")}`;
      lines.push(`  ${symbol.name}: database.${symbol.name} satisfies ${type},`);
    }
  }
  const constants = symbols.filter(
    (symbol) => symbol.entry_point === "./database" && symbol.kinds.includes("other const"),
  );
  for (const symbol of constants.sort((left, right) => left.name.localeCompare(right.name))) {
    const typeText = symbol.meanings[0]?.type_text;
    if (symbol.name === "SQL_SCHEMA_VERSION") {
      // The SQL step is a version declaration: 4 in 2.1.0, 5 in 2.1.1.
      lines.push(`  ${symbol.name}: database.${symbol.name} satisfies number,`);
    } else if (typeText !== null && typeText !== undefined) {
      lines.push(`  ${symbol.name}: database.${symbol.name} satisfies ${typeText},`);
    }
  }
  lines.push("};", "");
  return lines.join("\n");
}

const isMain = process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const inventory = JSON.parse(readFileSync(inventoryPath, "utf8"));
  const text = generate(inventory);
  if (process.argv.includes("--check")) {
    const committed = readFileSync(outputPath, "utf8");
    if (committed !== text) {
      console.error(`${outputPath} is out of date; run node scripts/generate-api-check.mjs`);
      process.exit(1);
    }
  } else {
    writeFileSync(outputPath, text);
  }
}
